  4789	    md_analyze_table_alignment(ctx, lines[1].beg, lines[1].end, align, col_count);
  4790	
  4791	    MD_ENTER_BLOCK(MD_BLOCK_THEAD, NULL);
  4792	    MD_CHECK(md_process_table_row(ctx, MD_BLOCK_TH,
  4793	                        lines[0].beg, lines[0].end, align, col_count));
  4794	    MD_LEAVE_BLOCK(MD_BLOCK_THEAD, NULL);
  4795	
  4796	    if(n_lines > 2) {
  4797	        MD_ENTER_BLOCK(MD_BLOCK_TBODY, NULL);
  4798	        for(line_index = 2; line_index < n_lines; line_index++) {
  4799	            MD_CHECK(md_process_table_row(ctx, MD_BLOCK_TD,
  4800	                     lines[line_index].beg, lines[line_index].end, align, col_count));
  4801	        }
  4802	        MD_LEAVE_BLOCK(MD_BLOCK_TBODY, NULL);
  4803	    }
  4804	
  4805	abort:
  4806	    free(align);
  4807	    return ret;
  4808	}
